#addSyncAccounts(syncAccounts) {
  for (const calendar of syncAccounts.calendars) {
    lazy.cal.manager.registerCalendar(calendar);
  }

  for (const addressBook of syncAccounts.addressBooks) {
    addressBook.create();
  }

create() {
  const dirPrefId = MailServices.ab.newAddressBook(
    this.name,
    null,
    Ci.nsIAbManager.CARDDAV_DIRECTORY_TYPE,
    null
  );
  const book = MailServices.ab.getDirectoryFromId(dirPrefId);
  book.setStringValue("carddav.url", this.url);

  if (!isWritable && isReadable) {
    book.setBoolValue("readOnly", true);

book.setStringValue("carddav.username", bookUsername);

const dir = lazy.CardDAVDirectory.forFile(book.fileName);
// Pass the context to the created address book. This prevents asking
// for a username/password again in the case that we didn't save it.
// The user won't be prompted again until Thunderbird is restarted.
dir._userContextId = userContextId;

// Trigger the initial sync with the server. Do not do this async,
// as it's not required before returning the directory.
authPromise.then(() => dir.fetchAllFromServer()).catch(console.error);

return dir;
